Solution A: ```javascript
function generateMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas || canvas.width !== 500 || canvas.height !== 500) return;
    const ctx = canvas.getContext('2d');

    const GRID_SIZE = 100; // 5px cells
    const CELL_SIZE = 5;
    const WALL = 0, FLOOR = 1, SPAWN = 2, WEAPON = 3;

    // Create or reset UI elements
    let button = document.getElementById('genBtn');
    let legend = document.getElementById('legendCanvas');
    if (!button) {
        button = document.createElement('button');
        button.id = 'genBtn';
        button.textContent = 'Generate New Map';
        button.style.position = 'absolute';
        button.style.top = '10px';
        button.style.left = '10px';
        button.style.zIndex = 10;
        document.body.appendChild(button);
    }
    if (!legend) {
        legend = document.createElement('canvas');
        legend.id = 'legendCanvas';
        legend.width = 120;
        legend.height = 120;
        legend.style.position = 'absolute';
        legend.style.top = '10px';
        legend.style.right = '10px';
        legend.style.border = '1px solid #000';
        legend.style.zIndex = 10;
        document.body.appendChild(legend);
    }

    // Draw legend
    function drawLegend() {
        const lctx = legend.getContext('2d');
        lctx.clearRect(0, 0, legend.width, legend.height);
        const items = [
            { color: '#000000', text: 'Wall', y: 20 },
            { color: '#A9A9A9', text: 'Floor', y: 50 },
            { color: '#00FF00', text: 'Spawn', y: 80 },
            { color: '#FF0000', text: 'Weapon', y: 110 }
        ];
        lctx.font = '14px Arial';
        items.forEach(i => {
            lctx.fillStyle = i.color;
            lctx.fillRect(10, i.y - 15, 20, 20);
            lctx.fillStyle = '#000';
            lctx.fillText(i.text, 40, i.y - 5);
        });
    }

    // Generate a map ensuring connectivity
    function createMap() {
        const grid = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(WALL));
        const rooms = [];
        const maxRooms = 8;
        const minSize = 10, maxSize = 30;

        function rectOverlap(r1, r2) {
            return !(r2.x > r1.x + r1.w ||
                     r2.x + r2.w < r1.x ||
                     r.y > r1.y + r1.h ||
                     r2.y + r2.h < r1.y);
        }

        for (let i = 0; i < maxRooms; i++) {
            const w = Math.floor(Math.random() * (maxSize - minSize + 1)) + minSize;
            const h = Math.floor(Math.random() * (maxSize - minSize + 1)) + minSize;
            const x = Math.floor(Math.random() * (GRID_SIZE - w - 1)) + 1;
            const y = Math.floor(Math.random() * (GRID_SIZE - h - 1)) + 1;
            const newRoom = {x, y, w, h};

            let overlap = rooms.some(r => rectOverlap(r, newRoom));
            if (overlap) continue; // skip overlapping

            rooms.push(newRoom);
            for (let rx = x; rx < x + w; rx++)
                for (let ry = y; ry < y + h; ry++)
                    grid[ry][rx] = FLOOR;
        }

        // Connect rooms with corridors
        function connect(r1, r2) {
            const cx1 = Math.floor(r1.x + r1.w / 2);
            const cy1 = Math.floor(r1.y + r1.h / 2);
            const cx2 = Math.floor(r2.x + r2.w / 2);
            const cy2 = Math.floor(r2.y + r2.h / 2);

            if (Math.random() < 0.5) {
                for (let x = Math.min(cx1, cx2); x <= Math.max(cx1, cx2); x++)
                    grid[cy1][x] = FLOOR;
                for (let y = Math.min(cy1, cy2); y <= Math.max(cy1, cy2); y++)
                    grid[y][cx2] = FLOOR;
            } else {
                for (let y = Math.min(cy1, cy2); y <= Math.max(cy1, cy2); y++)
                    grid[y][cx1] = FLOOR;
                for (let x = Math.min(cx1, cx2); x <= Math.max(cx1, cx2); x++)
                    grid[cy2][x] = FLOOR;
            }
        }
        for (let i = 1; i < rooms.length; i++)
            connect(rooms[i - 1], rooms[i]);

        // Find floor cells
        const floorCells = [];
        for (let y = 0; y < GRID_SIZE; y++)
            for (let x = 0; x < GRID_SIZE; x++)
                if (grid[y][x] === FLOOR) floorCells.push([x, y]);

        // Place spawns
        function pickSpawn() {
            let cell;
            do {
                const idx = Math.floor(Math.random() * floorCells.length);
                cell = floorCells[idx];
            } while (grid[cell[1]][cell[0]] !== FLOOR);
            grid[cell[1]][cell[0]] = SPAWN;
            return cell;
        }
        const spawn1 = pickSpawn();
        const spawn2 = pickSpawn();

        // Place weapons
        function pickWeapon() {
            let cell;
            do {
                const idx = Math.floor(Math.random() * floorCells.length);
                cell = floorCells[idx];
            } while (grid[cell[1]][cell[0]] !== FLOOR);
            grid[cell[1]][cell[0]] = WEAPON;
            return cell;
        }
        for (let i = 0; i < 5; i++) pickWeapon();

        // Flood fill for connectivity
        const visited = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(false));
        const queue = [spawn1, spawn2];
        visited[spawn1[1]][spawn1[0]] = true;
        visited[spawn2[1]][spawn2[0]] = true;
        const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        while (queue.length) {
            const [x, y] = queue.shift();
            for (const [dx, dy] of dirs) {
                const nx = x + dx, ny = y + dy;
                if (nx>=0 && nx<GRID_SIZE && ny>=0 && ny<GRID_SIZE &&
                    !visited[ny][nx] && (grid[ny][nx]===FLOOR || grid[ny][nx]===SPAWN || grid[ny][nx]===WEAPON)) {
                    visited[ny][nx] = true;
                    queue.push([nx, ny]);
                }
            }
        }
        // Check for unreachable floors
        const unreachable = grid.some((row, y) => row.some((v, x) => v===FLOOR && !visited[y][x]));
        return {grid, unreachable};
    }

    // Main rendering function
    function render(grid) {
        const imgData = ctx.createImageData(canvas.width, canvas.height);
        const data = imgData.data;
        for (let y = 0; y < GRID_SIZE; y++) {
            for (let x = 0; x < GRID_SIZE; x++) {
                const value = grid[y][x];
                const color = value === WALL ? [0, 0, 0] :
                              value === FLOOR ? [169, 169, 169] :
                              value === SPAWN ? [0, 255, 0] :
                              value === WEAPON ? [255, 0, 0] : [255, 255, 255];
                for (let dy = 0; dy < CELL_SIZE; dy++) {
                    for (let dx = 0; dx < CELL_SIZE; dx++) {
                        const px = (x * CELL_SIZE + dx) * 4;
                        const py = (y * CELL_SIZE + dy) * 4;
                        const idx = py * canvas.width + px;
                        data[idx] = color[0];
                        data[idx+1] = color[1];
                        data[idx+2] = color[2];
                        data[idx+3] = 255;
                    }
                }
            }
        }
        ctx.putImageData(imgData, 0, 0);
    }

    // Generate new map
    function generate() {
        let attempt = 0;
        let result;
        while (attempt < 50) {
            result = createMap();
            if (!result.unreachable) break;
            attempt++;
        }
        if (attempt === 50) console.warn('Failed to generate connected map.');
        render(result.grid);
        drawLegend();
    }

    button.onclick = generate;
    generate();
}
